import{_ as r,l as n,o as a,c as d,v as i,p as c,x as t,d as l,i as s,S as p}from"./chunks/framework.InCnrqk-.js";const C=JSON.parse('{"title":"强度削弱与归纳变量","description":"","frontmatter":{"title":"强度削弱与归纳变量","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/strength-reduction-iv.md","filePath":"cs/strength-reduction-iv.md","lastUpdated":1789023840000}'),h={name:"cs/strength-reduction-iv.md"};function _(u,e,m,f,k,b){const o=n("Mermaid");return a(),d("div",null,[e[1]||(e[1]=i('<h1 id="强度削弱与归纳变量" tabindex="-1">强度削弱与归纳变量 <a class="header-anchor" href="#强度削弱与归纳变量" aria-label="Permalink to &quot;强度削弱与归纳变量&quot;">​</a></h1><div class="epigraph"><p>归纳变量每圈加常数；乘以常数的地址可改成每圈加法。强度削弱把贵运算换成便宜更新。</p><footer>—— 据 Allen, Cocke, Cocke–Kennedy；龙书归纳变量；Muchnick 整理</footer></div><p>上一课<a href="/cs/licm">LICM</a>把不变式搬出去。缺口是<strong>随圈线性变</strong>的量：<code>a[i]</code> 的地址 <code>&amp;a + i*sizeof</code>。基本归纳变量 \\(i\\)，派生 \\(j=4*i+b\\)。削弱：循环外算初值，圈内 <code>j+=4</code>。本课钉 IV 与削弱，不写展开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>识别：SSA 上 \\(i = \\phi(i_0, i+c)\\) 形态。派生：循环内 \\(j = i*k + b\\) 且 \\(k,b\\) 不变。缺口是<strong>改写合法性</strong>（溢出、指针 provenance），不是外提。</p><p>删除无用 IV：若 \\(i\\) 只服务地址，削弱后 \\(i\\) 可 DCE。比较：<code>i&lt;n</code> 可改成 <code>p&lt;end</code>，少一个名——重写退出条件。</p><h3 id="削弱不是「乘法变移位」的窥孔" tabindex="-1">削弱不是「乘法变移位」的窥孔 <a class="header-anchor" href="#削弱不是「乘法变移位」的窥孔" aria-label="Permalink to &quot;削弱不是「乘法变移位」的窥孔&quot;">​</a></h3><p>窥孔把 <code>*4</code> 变移位，是单条指令。IV 削弱是跨迭代的递推。二者都做，层不同。</p><p><span class="marginnote">Cocke–Kennedy 强度削弱。龙书 9.1.2。LLVM 的 IndVarSimplify。本课整数与指针；浮点归纳少见且危险。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>找循环的 φ 加法。建 IV 族。为每个派生插初始化与加法。更新比较。跑 DCE。</p>',11)),(a(),c(p,null,{default:t(()=>[s(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PHI%5B%22i%20%3D%20%CF%86(i0%2C%20i%2Bc)%22%5D%20--%3E%20FAM%5B%22%E6%B4%BE%E7%94%9F%20j%20%3D%20k*i%2Bb%22%5D%0A%20%20FAM%20--%3E%20SR%5B%22j%20%2B%3D%20k*c%22%5D%0A%20%20SR%20--%3E%20DCE%5B%22%E5%88%A0%E6%97%A0%E7%94%A8%20i%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[l(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i('<p>与寄存器：多个派生 IV 增加名，可能要合并或保留 \\(i\\)。启发。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>有符号溢出：C 中 \\(i\\) 递增若 UB，削弱后的指针运算须仍在对象内——语言规则。不要把 <code>i*i</code> 当线性 IV。</p><p>非线性（<code>i*i</code>）可差分化成递推，少见，点名。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写循环展开因子选择。后课默认：线性 IV 可削弱成加法。下一课展开与剥离：用已知行程复制体。</p><p>也不把强度削弱当密码学的「削弱」。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>基本 IV 每圈加常数；派生可递推更新。</li><li>削弱后 DCE 旧 IV；注意溢出与指针规则。</li><li>不同于单指令窥孔。</li><li>出处：Allen/Cocke/Kennedy；龙书；Muchnick。</li></ul>',9))])}const V=r(h,[["render",_]]);export{C as __pageData,V as default};
